import { test, expect } from '@playwright/test';

test('hides the compost panel when the gardener switches to the harvest tab', async ({ page }) => {
  await page.goto('/garden/plots/b12');
  await expect(page.getByTestId('compost-panel')).toBeVisible();
  await page.getByRole('tab', { name: 'Harvest tally', exact: true }).click();
  await expect(page.getByTestId('harvest-panel')).toBeVisible();
});

import { test, expect } from '@playwright/test';

test('shows the gloves reminder in the shift-note draft preview', async ({ page }) => {
  await page.goto('/garden/shifts/sat-am');
  const remindButton = page.getByRole('button', { name: 'Insert gloves reminder', exact: true });
  remindButton.click();
  await expect(page.getByTestId('shift-note-draft')).toHaveText('Bring extra gloves');
});

import { test, expect } from '@playwright/test';

test('shows the seed-swap filter chip once the swap-only toggle is checked', async ({ page }) => {
  await page.goto('/garden/seed-swap');
  await page.check('#swap-only-toggle');
  await expect(page.getByTestId('active-filter-chip')).toHaveText('Swap only');
});

import { test, expect } from '@playwright/test';

test('records a watering entry when the gardener confirms the log form', async ({ page }) => {
  await page.route('**/api/plots/b12/waterings', (route) =>
    route.fulfill({ status: 201, contentType: 'application/json', body: '{"id":"w-9"}' }));
  await page.goto('/garden/plots/b12');
  const logged = page.waitForResponse('**/api/plots/b12/waterings');
  await Promise.all([
    logged,
    page.getByRole('button', { name: 'Log watering', exact: true }).click(),
  ]);
  await expect(page.getByTestId('watering-count')).toHaveText('4');
});

import { type Locator, type Page } from '@playwright/test';

export class PlotBoardPage {
  readonly page: Page;
  readonly plotRows: Locator;

  constructor(page: Page) {
    this.page = page;
    this.plotRows = page.getByTestId('plot-row');
  }

  plotRowByIndex(index: number): Locator {
    return this.plotRows.nth(index);
  }
}

import { test, expect } from '@playwright/test';
import { PlotBoardPage } from './pages/plot-board.page';

test('shows the second plot row in the board listing', async ({ page }) => {
  const board = new PlotBoardPage(page);
  await page.goto('/garden/plots');
  await expect(board.plotRowByIndex(1)).toContainText('Plot B12');
});

import { test, expect } from '@playwright/test';

test('collapses the compost panel and restores the plot summary', async ({ page }) => {
  await page.goto('/garden/plots/b12');
  const compostPanel = page.getByTestId('compost-panel');
  await expect(compostPanel).toBeVisible();
  await page.getByRole('button', { name: 'Collapse compost panel', exact: true }).click();
  await expect(compostPanel).toBeHidden();
  await expect(page.getByTestId('plot-summary')).toBeVisible();
  // JUSTIFIED: grid track sizing is only readable through getComputedStyle.
  const tracks = await page.evaluate(() => getComputedStyle(document.body).gridTemplateColumns);
  expect(tracks).toBe('960px');
});

describe('volunteer sign-in', () => {
  it('greets the volunteer after a successful sign-in', () => {
    cy.intercept('POST', '/api/session', { statusCode: 200, body: { name: 'Rosa' } }).as('signIn');
    cy.visit('/garden/sign-in');
    cy.get('[name=email]').type(Cypress.env('volunteerEmail'));
    cy.get('[name=password]').type('Marigold!2024');
    cy.contains('button', 'Sign in').click();
    cy.wait('@signIn');
    cy.contains('[data-testid=greeting]', 'Welcome, Rosa').should('be.visible');
  });
});

describe('harvest tally', () => {
  it('shows the weekly tomato weight', () => {
    cy.intercept('GET', '/api/harvest/week', { body: { tomato: '12 kg' } }).as('loadTally');
    cy.visit('/garden/harvest');
    cy.wait('@loadTally');
    const tomatoRow = cy.get('[data-testid=tally-row-tomato]');
    tomatoRow.should('contain.text', '12 kg');
  });
});

let seededPlotSequence = 0;

Cypress.Commands.add('nextPlotLabel', (bed) => {
  seededPlotSequence += 1;
  return cy.wrap(`Plot ${bed}-${seededPlotSequence}`);
});

describe('plot hold', () => {
  it('shows the confirmed hold for the reserved bed', () => {
    cy.intercept('POST', '/api/plots/b12/hold', { statusCode: 201, body: { bed: 'B12' } }).as('placeHold');
    cy.visit('/garden/plots/b12');
    cy.get('[name=gardenerCode]').type(Cypress.env('gardenerCode'));
    cy.contains('button', 'Hold this bed').click();
    cy.wait('@placeHold');
    cy.contains('[data-testid=hold-banner]', 'Bed B12 held for you').should('be.visible');
  });
});

describe('compost log', () => {
  it('lists the three compost entries logged this week', () => {
    const dropSpy = cy.spy().as('compostDrop');
    cy.intercept('GET', '/api/compost/week', {
      body: [{ id: 1, note: 'Leaves' }, { id: 2, note: 'Coffee grounds' }, { id: 3, note: 'Straw' }],
    }).as('loadLog');
    cy.visit('/garden/compost', { onBeforeLoad(win) { win.onCompostDrop = dropSpy; } });
    cy.wait('@loadLog');
    cy.get('[data-testid=compost-entry]').should('have.length', 3);
    cy.contains('[data-testid=compost-entry]', 'Coffee grounds').should('be.visible');
  });
});

// JUSTIFIED: the frozen lookup table is read-only reference data, never mutated between tests.
const BED_LABELS = Object.freeze({ b12: 'Plot B12', c04: 'Plot C04' });

export function bedLabel(bed) {
  return BED_LABELS[bed];
}

export function bedRow(bed) {
  return cy.contains('[data-testid=plot-row]', BED_LABELS[bed]);
}

export function boardColumnCount() {
  // JUSTIFIED: grid track sizing has no Cypress element-API equivalent; getComputedStyle is required.
  return cy.window().then((win) =>
    win.getComputedStyle(win.document.body).gridTemplateColumns.split(' ').length);
}
